<link rel="stylesheet" href="<?= base_url('assets/vendor/leaflet/leaflet.css') ?>">
<div class="intro-line"><p>Peta menampilkan titik yang sudah diisi. Identitas yang belum memiliki koordinat tetap terlihat dalam daftar untuk dilengkapi petugas.</p><span class="count-chip"><?= number_format($all_mapped,0,',','.') ?> / <?= number_format($all_total,0,',','.') ?> koperasi bertitik · <?= count($kdkmp_points) ?> titik lokasi KDKMP dalam filter</span></div>
<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari koperasi</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Nama atau NIK"></label><label><span>Titik</span><select name="mapping"><option value="">Semua</option><option value="mapped" <?= $mapping==='mapped'?'selected':'' ?>>Sudah ada</option><option value="unmapped" <?= $mapping==='unmapped'?'selected':'' ?>>Belum ada</option></select></label><label><span>Jenis</span><select name="type"><option value="">Semua jenis</option><?php foreach ($types as $x): ?><option value="<?= $x['id'] ?>" <?= (string)$type===(string)$x['id']?'selected':'' ?>><?= h($x['name']) ?></option><?php endforeach; ?></select></label><label><span>Kecamatan</span><select name="district"><option value="">Semua</option><?php foreach ($districts as $x): ?><option value="<?= $x['id'] ?>" <?= (string)$district===(string)$x['id']?'selected':'' ?>><?= h($x['name']) ?></option><?php endforeach; ?></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path) ?>">Reset</a></form>
<div class="map-panel"><div id="cooperative-map" role="application" aria-label="Peta lokasi koperasi Rembang"></div><?php if (!$mapped && !$kdkmp_points): ?><div class="map-empty">Belum ada titik untuk filter ini. Lengkapi koordinat koperasi atau lokasi KDKMP melalui profilnya.</div><?php endif; ?></div>
<div class="table-wrap"><table><thead><tr><th>Koperasi</th><th>Jenis</th><th>Kecamatan</th><th>Koordinat</th><th>Lingkup</th><th></th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><strong><?= h($r['name']) ?></strong><small class="cell-sub mono"><?= h($r['nik']) ?></small></td><td><?= h($r['type_name']) ?></td><td><?= h($r['district_name']) ?></td><td><?= $r['latitude']!==null?h($r['latitude'].', '.$r['longitude']):'<span class="pill pill-muted">Belum ada</span>' ?></td><td><?= $r['reference_only']?'Referensi':'Kabupaten' ?></td><td><?php if ($allowed_nav['koperasi']): ?><a class="row-link" href="<?= site_url('admin/koperasi/'.$r['id']) ?>">Profil →</a><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="6" class="empty-cell">Tidak ada lokasi yang sesuai filter.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
<script src="<?= base_url('assets/vendor/leaflet/leaflet.js') ?>"></script>
<script>
const gisPoints=<?= json_encode(array_map(function($r){return array('id'=>$r['id'],'name'=>$r['name'],'lat'=>(float)$r['latitude'],'lon'=>(float)$r['longitude']);},$mapped),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE) ?>;
const kdkmpPoints=<?= json_encode(array_map(function($r){return array('id'=>$r['id'],'name'=>$r['name'],'lat'=>(float)$r['latitude'],'lon'=>(float)$r['longitude']);},$kdkmp_points),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE) ?>;
const gisMap=L.map('cooperative-map',{scrollWheelZoom:false}).setView([-6.709,111.347],10);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(gisMap);
const cooperativeLayer=L.featureGroup().addTo(gisMap),kdkmpLayer=L.featureGroup().addTo(gisMap),allPoints=L.featureGroup();
for(const point of gisPoints){const a=document.createElement('a');a.href='<?= site_url('admin/koperasi/') ?>'+point.id;a.textContent=point.name+' →';const box=document.createElement('div');box.append(a);L.marker([point.lat,point.lon]).bindPopup(box).addTo(cooperativeLayer);L.marker([point.lat,point.lon]).addTo(allPoints);}
for(const point of kdkmpPoints){const box=document.createElement('div');const strong=document.createElement('strong');strong.textContent=point.name;box.append(strong);<?php if ($allowed_nav['kdkmp']): ?>const a=document.createElement('a');a.href='<?= site_url('admin/kdkmp/') ?>'+point.id;a.textContent=' Buka KDKMP →';box.append(a);<?php endif; ?>L.circleMarker([point.lat,point.lon],{radius:8,color:'#9b442b',fillColor:'#bd6642',fillOpacity:.9,weight:2}).bindPopup(box).addTo(kdkmpLayer);L.marker([point.lat,point.lon]).addTo(allPoints);}
L.control.layers(null,{'Koperasi':cooperativeLayer,'Lokasi KDKMP':kdkmpLayer},{collapsed:false}).addTo(gisMap);
if(gisPoints.length || kdkmpPoints.length)gisMap.fitBounds(allPoints.getBounds().pad(.2),{maxZoom:13});
</script>
